using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.Quotations.Dtos;using Namaa.Domain.Common.Errors;using Namaa.Domain.Common.Results;namespace Namaa.Application.Quotations.Queries.GetQuotationById;public sealed class GetQuotationByIdQueryHandler(IQuotationRepository repository):IRequestHandler<GetQuotationByIdQuery,Result<QuotationDto>>{public async Task<Result<QuotationDto>>Handle(GetQuotationByIdQuery request,CancellationToken cancellationToken){var e=await repository.FindByIdAsync(request.Id,cancellationToken);return e is null?Result.Failure<QuotationDto>(QuotationErrors.NotFound):Result.Success(QuotationDto.FromEntity(e));}}

